#!/usr/bin/env bash
set -e
echo "Remplacement des illustrations par les vraies photos fournies..."

rm -f "public/placeholders/don.png"
rm -f "public/placeholders/entraide.png"
rm -f "public/placeholders/covoiturage.png"
rm -f "public/placeholders/cherche.png"
rm -f "public/placeholders/alerte.png"

mkdir -p "src/lib"
cat > "src/lib/placeholderImages.js" << 'MQEOF_SRC_LIB_PLACEHOLDERIMAGES_JS'
// Illustration générique affichée automatiquement quand une annonce ou une
// activité n'a pas de vraie photo — évite les cases vides.
//
// Les 5 catégories d'annonces (don, entraide, covoiturage, cherche, alerte)
// utilisent de vraies photos fournies (JPEG) ; les catégories d'activités
// et de commerces utilisent des illustrations vectorielles simples (PNG).

const JPEG_TYPES = new Set(['don', 'entraide', 'covoiturage', 'cherche', 'alerte']);

export function getPlaceholderImage(type) {
  const ext = JPEG_TYPES.has(type) ? 'jpg' : 'png';
  return `/placeholders/${type}.${ext}`;
}

MQEOF_SRC_LIB_PLACEHOLDERIMAGES_JS

mkdir -p "public/placeholders"
base64 -d > "public/placeholders/don.jpg" << 'MQB64EOF_PUBLIC_PLACEHOLDERS_DON_JPG'

MQB64EOF_PUBLIC_PLACEHOLDERS_DON_JPG

mkdir -p "public/placeholders"
base64 -d > "public/placeholders/entraide.jpg" << 'MQB64EOF_PUBLIC_PLACEHOLDERS_ENTRAIDE_JPG'

MQB64EOF_PUBLIC_PLACEHOLDERS_ENTRAIDE_JPG

mkdir -p "public/placeholders"
base64 -d > "public/placeholders/covoiturage.jpg" << 'MQB64EOF_PUBLIC_PLACEHOLDERS_COVOITURAGE_JPG'

MQB64EOF_PUBLIC_PLACEHOLDERS_COVOITURAGE_JPG

mkdir -p "public/placeholders"
base64 -d > "public/placeholders/cherche.jpg" << 'MQB64EOF_PUBLIC_PLACEHOLDERS_CHERCHE_JPG'

MQB64EOF_PUBLIC_PLACEHOLDERS_CHERCHE_JPG

mkdir -p "public/placeholders"
base64 -d > "public/placeholders/alerte.jpg" << 'MQB64EOF_PUBLIC_PLACEHOLDERS_ALERTE_JPG'

MQB64EOF_PUBLIC_PLACEHOLDERS_ALERTE_JPG

echo "Photos d'annonces remplacees avec succes."
echo "Prochaine etape : git add -A && git commit -m \"photos reelles pour les 5 categories annonces\" && git push"